import Foundation

/// Die In-App-Hilfe (SICK-039) als reine Daten: Ein Thema je Bedienweg,
/// in der Reihenfolge des Spielablaufs. Die Ansicht rendert nur; der
/// Text beschreibt, was die App tut und was sie ausdrücklich nicht tut.
public struct HelpTopic: Equatable, Identifiable, Sendable {
    public let id: String
    public let title: String
    public let body: String

    public init(id: String, title: String, body: String) {
        self.id = id
        self.title = title
        self.body = body
    }
}

public enum HelpTopics {
    public static let all: [HelpTopic] = [
        .init(id: "verbinden", title: "Connect", body: "Choose a port and click Connect. The scanner uses Full scan 361 only; old saved mode choices are ignored. A running CRC-valid 361 stream is adopted without sending commands. Otherwise setup requests Full scan at 500000 baud, repeats unanswered commands and waits at least four seconds for login and mode replies. Three new 361 profiles confirm success. Setup releases outputs and closes RX before setup; setup closes TX before RX begins. Failed or aborted setup shows the observed point count and baud rate with one next action. Unreachable means no CRC-valid telegram was received at any supported rate. Ready shows measured points and rate. The owner measured about 25 Hz for full scan at 500000 baud. Development retains individual diagnostic steps."),
        .init(id: "device-fields", title: "Device fields", body: "Device fields opens a separate offline editor for Protective field (up to 4 m, OSSD 1/2) and Warning field (up to 50 m, WEAK SIGNAL). Drag selects cells; Option-drag brushes; Fill and Erase modify the selected field. Select or Pan uses the usual field tools. Semicircle and Rectangle create meter-sized reference shapes. Islands, rings, gaps and detail below segment resolution are named in validation. Choose 90, 180 or 360 segments; 180 has no verified wire format and cannot be exported. Export contour writes diagnostic bytes only to a file and shows the difference from the last successful export. Show device fields controls the edit and performance displays separately; performance permits display only. These Mac-local fields never enter a preset, never play, and make no safety function claim."),
        .init(id: "workspace", title: "Workspace and performance", body: "Use View or ⌘1–4 to show Setup, Layers, Cell and the channel strip. Narrow windows use inspector tabs. Perform (⌘⇧P) hides inspectors and locks cell painting, moving and selection; zoom and pan remain available. Edit restores your previous layout. Input lost turns the status bar red without opening Setup. Full screen is independent of performance mode."),
        .init(id: "scenes", title: "Scenes and switch cells", body: "A scene stores which layers play (M off) and which are muted. Click its name above the field to activate it. + creates a scene; the context menu renames, updates, moves or deletes it. Layer dots toggle scene membership. Select switch cells and choose Next, Previous or a named scene in Cell. Without selection the Layers assignment changes the layer default. Reset to layer removes own cell targets. A missing scene does nothing. Switch cells act immediately on entry and re-arm only after leaving. Simultaneous switches run in layer/routing order, then ring and angle."),
        .init(id: "zonen", title: "Layers and cells", body: "Paint cells in the active layer with B and choose Output and Controls in the inspector. In the Layers list, ⌘D duplicates a layer and ⌘C/⌘V copy or paste layers; the layer context menu offers the same actions. In the field these shortcuts act on selected cells. Pasted layers join the active scene, while a duplicate keeps every scene membership of its original. Only measured scan points open notes and gates."),
        .init(id: "move-cells", title: "Select and edit cells", body: "V selects painted cells of visible, unlocked layers. Click selects the top layer; ⇧ extends a range and ⌘ toggles one cell. Drag empty space or an unselected cell to select a rectangle across layers. The toolbar switch Click selects: Cell | Area swaps click and double-click: Area clicks select the island, double-clicks a cell; ⇧ adds and ⌘ toggles. Double-click in Cell mode selects an edge-connected island of equal effective notes or values in one layer; ⇧ adds the island and ⌘ toggles it. Corner contact does not connect islands. Click a layer in the list or choose Select layer in the field context menu to select the whole layer. Drag selected cells to move; hold ⌥ to copy. The frame’s arcs resize distance, edges resize angle, corners resize both. Arrow keys move one step, ⇧ ten. ⌫ deletes cells and own values. ⌘A selects eligible cells; ⌘D duplicates cells in the field and layers in the list. ⌘C/⌘X/⌘V copy, cut and paste cells with own values in the field; missing original layers fall back to the active layer. Right-click edits the selection or offers painting in the active layer. Each gesture is one undo step; ⌘Z undoes it. Esc cancels a gesture or clears selection. Field-edge and no-effect notices appear below the field."),
        .init(id: "felder", title: "Scan field tools", body: "V Select: click, rectangle, move or resize the selected painted cells. B Paint: click or drag paints in the active layer named above the field. E Erase: click or drag removes cells and own values from that layer. H Hand: drag pans. Holding Space temporarily uses Hand; trackpad pan and pinch remain available with every tool. Locked or hidden layers cannot be edited. The field uses polar segments in centimeters; changing the paint grid preserves existing cells."),
        .init(id: "kanalzug", title: "Mixer channels and sum", body: "Each of up to eight channels owns its instrument, inserts, fader, pan, mute and solo. + adds an empty channel. The channel context menu offers Rename, Color, Duplicate and Delete. Duplicate loads new plug-in instances with the same state; layers keep their original target. Delete asks when layers use that channel and releases its notes first. Choose a channel with the Output buttons in Layers. A missing channel stays silent until you choose another one. Held chords are replaced only by triggers on the same channel. Narrow mixers scroll horizontally. Perform shows all mini channels and Sum. The only PANIC button is at Sum in both modes and releases all outputs. Sum controls the master gain and meter; its red overload indicator can be clicked to reset."),
        .init(id: "audiounits", title: "Audio Units", body: "Choose an instrument or insert from the system catalog. Loading, loaded, bypassed and failed states come from the host. Each plug-in has its own editor window."),
        .init(id: "midi", title: "MIDI", body: "MIDI is a parallel output of the same performance. Choose a destination in the channel strip. Panic releases notes on every bound output; the next valid profile can play again."),
        .init(id: "presets", title: "Presets", body: "V6 presets store all channels and plug-in states, Sum, layers, detection settings and viewport. Use Import Preset… to add checked JSON files without changing the current preset; Export Preset… writes the complete current V6 preset. V3–V5 presets migrate to one channel named Ch 1. Spatial templates omit the mixer and preserve the live channels. Room contour evidence is never stored."),
        .init(id: "toggle", title: "Toggle loops", body: "Choose Single note or Chord, then Toggle: on / next entry off in the layer transition menu. Single note uses one piano key and velocity throughout the layer. First measured entry starts a painted surface's notes; movement inside it and leaving keep them playing. Enter the surface again after leaving to turn them off. Connected cells with the same own contents share one entry; different own contents and separate surfaces switch independently. Cell overrides inherit the layer transition. Scale and Random scale do not offer Toggle; older presets change to Retrigger on load with a notice. Shared notes stop only when their last owner releases. Deleting, moving or changing the routing releases affected loops."),
        .init(id: "release-layer", title: "Release layer", body: "Choose Release layer as the layer output, then choose the default target layer. In Cell, selected cells can choose their own target; Reset to layer restores the default. Fresh measured entry releases only that target layer's held and toggled notes. The field shows Release followed by the target name. A missing layer does nothing. Control layers stay outside scenes."),
        .init(id: "loesen", title: "Panic and release", body: "Gate, Note-Off and Panic never come from prediction. Unexpected input loss releases ordinary notes; held and toggled notes keep playing. On return, leave a toggle cell before entering again to turn it off; Release layer or a new channel trigger can release held notes. Panic, stop, preset or instrument change, deliberate disconnect, input change, sleep and termination release everything. If audio was running before sleep, it resumes after wake; new notes need a fresh profile."),
        .init(id: "grenzen", title: "Device and support tools", body: "The discontinued scanners are used as musical inputs. Reading or writing fields makes no claim about a safety function or certification. Manual setup commands remain an explicit support action."),
    ]

    public static func topic(id: String) -> HelpTopic? {
        all.first { $0.id == id }
    }
}
